const app=document.getElementById('app');
let me=null,players=[],entries=[],adventures=[],users=[],archivedPlayers=[],auditLog=[],trash=[],trashAdventures=[],trashError='',schemaStatus=null,quality={players:[],entries:[]},prefs={xp_milestone_step:5000,xp_reminder_window:750,birthday_reminders:true},page='home',selectedAdventure=null,csvRows=[],restorePayload=null;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('it-IT').format(Number(n)||0),isAdmin=()=>me?.role==='admin',canEdit=()=>['admin','editor'].includes(me?.role);
const roleNames={admin:'Amministratore',editor:'Editor',viewer:'Visualizzatore'},localISO=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')},todayISO=localISO;
const PROTECTED_USERNAME='arcamis-admin';
const XP_LEVELS=[0,300,900,2700,6500,14000,23000,34000,48000,64000,85000,100000,120000,140000,165000,195000,225000,265000,305000,355000];
function levelInfo(xp){let total=Math.max(0,Number(xp)||0),level=1;for(let i=0;i<XP_LEVELS.length;i++)if(total>=XP_LEVELS[i])level=i+1;if(level>=XP_LEVELS.length)return {level:XP_LEVELS.length,current:XP_LEVELS[XP_LEVELS.length-1],next:null,remaining:0,pct:100,maxed:true};const current=XP_LEVELS[level-1],next=XP_LEVELS[level],remaining=next-total,pct=Math.max(0,Math.min(100,Math.round((total-current)/(next-current)*100)));return {level,current,next,remaining,pct,maxed:false}}
async function api(path,opts={}){let r;try{r=await fetch('/api/'+path,{...opts,headers:{'content-type':'application/json',...(opts.headers||{})},credentials:'same-origin'})}catch{const e=new Error('Connessione assente. Controlla la rete e riprova.');e.status=0;throw e}let d=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(d.error||'Richiesta non riuscita.');e.status=r.status;e.data=d;throw e}return d}
const post=(path,data)=>api(path,{method:'POST',body:JSON.stringify(data)}),put=(path,data)=>api(path,{method:'PUT',body:JSON.stringify(data)});
function brand(){return '<div class="brand"><div class="sigil"><img src="/logo.png" alt=""></div><div><b>ARCAMIS</b><small>ARCHIVIO D’AVVENTURA</small></div></div>'}
function message(form,msg){let n=form.querySelector('.error');if(!n){n=document.createElement('div');n.className='error';form.append(n)}n.textContent=msg}
function pageFromHash(){const h=decodeURIComponent((location.hash||'').replace(/^#/,''));return /^(home|players|sessions|calendar|admin|adventure)$/.test(h)||/^detail-[\w-]+$/.test(h)?h:'home'}
function setPage(next,opts={}){page=next;try{const hash='#'+next;if(location.hash!==hash){const fn=opts.replace?history.replaceState:history.pushState;fn.call(history,{page:next},'',hash)}}catch{}render()}
function applyDynamicStyles(){document.querySelectorAll('[data-h]').forEach(el=>{el.style.height=Math.max(0,Math.min(100,Number(el.dataset.h)||0))+'%'});document.querySelectorAll('[data-w]').forEach(el=>{el.style.width=Math.max(0,Math.min(100,Number(el.dataset.w)||0))+'%'})}
function showLoadError(msg){let b=document.getElementById('netBanner');if(!b){b=document.createElement('div');b.id='netBanner';b.className='net-banner';b.setAttribute('role','alert');b.innerHTML='<span></span><button type="button">Riprova</button>';document.body.append(b);b.querySelector('button').onclick=()=>{b.remove();load()}}b.querySelector('span').textContent=msg||'Impossibile aggiornare i dati.'}
function clearLoadError(){document.getElementById('netBanner')?.remove()}
let swUpdateReady=false;
async function registerWorker(){if(!('serviceWorker'in navigator))return;try{const reg=await navigator.serviceWorker.register('/sw.js');const check=w=>{if(w&&w.state==='installed'&&navigator.serviceWorker.controller)offerUpdate()};check(reg.waiting);reg.addEventListener('updatefound',()=>{const w=reg.installing;if(w)w.addEventListener('statechange',()=>check(w))});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(swUpdateReady){swUpdateReady=false;location.reload()}})}catch{}}
function offerUpdate(){if(document.getElementById('updateBanner'))return;const b=document.createElement('div');b.id='updateBanner';b.className='net-banner update-banner';b.setAttribute('role','status');b.innerHTML='<span>Nuova versione disponibile.</span><button type="button">Aggiorna</button>';document.body.append(b);b.querySelector('button').onclick=()=>{swUpdateReady=true;navigator.serviceWorker.controller?.postMessage({type:'SKIP_WAITING'})}}
addEventListener('popstate',()=>{const p=pageFromHash();if(p!==page){page=p;render()}});
async function boot(){addEventListener('offline',()=>showLoadError('Sei offline: i dati potrebbero non essere aggiornati.'));addEventListener('online',()=>{clearLoadError();load()});registerWorker();page=pageFromHash();try{if(!location.hash)history.replaceState({page},'','#home');let st=await api('setup-status');if(!st.configured)return setup();me=await api('me');await load()}catch(e){login(e.status===401?'':e.message)}}
function setup(){app.innerHTML=`<main class="auth"><div class="authbox">${brand()}<div class="eyebrow">Avvio riservato</div><h1>Crea l’account admin</h1><p class="sub">Inserisci il codice di configurazione impostato su Cloudflare. Questa schermata scompare dopo la creazione del primo account.</p><form id="setup"><label>Codice di configurazione<input name="secret" type="password" required></label><label>Nome utente admin<input name="username" minlength="3" required></label><label>Password admin<input name="password" type="password" minlength="12" required></label><button class="action">Crea amministratore</button><div class="error"></div></form></div></main>`;$('#setup').onsubmit=async e=>{e.preventDefault();try{await post('setup',Object.fromEntries(new FormData(e.target)));login('Account admin creato. Accedi per continuare.')}catch(x){message(e.target,x.message)}}}
function login(info=''){app.innerHTML=`<main class="auth"><div class="authbox">${brand()}<div class="eyebrow">Cronache della compagnia</div><h1>Accedi agli annali</h1>${info?`<p class="badge">${esc(info)}</p>`:''}<form id="login"><label>Nome utente<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="action">Accedi</button><div class="error"></div></form><p class="sub login-help">Gli account vengono creati dall’amministratore.</p></div></main>`;$('#login').onsubmit=async e=>{e.preventDefault();try{me=await post('login',Object.fromEntries(new FormData(e.target)));page='home';history.replaceState(null,'','#home');await load()}catch(x){message(e.target,x.message)}}}
function nav(){return `<aside class="side">${brand()}<nav class="nav"><button data-page="home" class="${page==='home'?'active':''}"><span>◈</span>Panoramica</button><button data-page="players" class="${page==='players'||page.startsWith('detail-')?'active':''}"><span>♙</span>Avventurieri</button><button data-page="sessions" class="${page==='sessions'||page==='adventure'?'active':''}"><span>▤</span>Registro XP</button>${isAdmin()?`<button data-page="admin" class="${page==='admin'?'active':''}"><span>⚙</span>Amministrazione</button>`:''}</nav><div class="sidefoot">✧ ${roleNames[me?.role]||'Account'} · Tutti gli annali</div></aside>`}
function totals(){let m=new Map(players.map(p=>[p.id,0]));entries.forEach(x=>m.set(x.player_id,(m.get(x.player_id)||0)+Number(x.xp||0)));return m}
function monthChart(){let sums=new Map();entries.forEach(e=>{if(!e.date)return;let k=e.date.slice(0,7);sums.set(k,(sums.get(k)||0)+Number(e.xp||0))});let vals=[...sums].sort((a,b)=>a[0].localeCompare(b[0])).slice(-6),max=Math.max(1,...vals.map(v=>v[1]));return `<div class="chart">${vals.map(([m,v])=>`<div class="barcol"><div class="barvalue">${fmt(v)}</div><div class="bar" data-h="${Math.max(5,v/max*100)}"></div><small>${new Date(m+'-15').toLocaleDateString('it-IT',{month:'short',year:'2-digit'})}</small></div>`).join('')||'<div class="empty">I dati delle sessioni compariranno qui.</div>'}</div>`}
function daysToBirthday(v){if(!v||!/^\d{4}-\d{2}-\d{2}$/.test(v))return null;let now=new Date(),b=new Date(now.getFullYear()+'-'+v.slice(5)+'T12:00:00'),today=new Date(now.toISOString().slice(0,10)+'T12:00:00');if(b<today)b.setFullYear(now.getFullYear()+1);return Math.floor((b-today)/86400000)}
function home(){let xp=entries.reduce((a,x)=>a+Number(x.xp||0),0),uniq=groups().length,ts=totals(),top=[...players].sort((a,b)=>(ts.get(b.id)||0)-(ts.get(a.id)||0)).slice(0,5),recent=groups().slice(0,6);return `<section class="cards"><div class="card"><label>Avventurieri attivi</label><div class="metric">${players.filter(p=>(p.status||'Attivo')!=='Inattivo').length}</div></div><div class="card"><label>Sessioni registrate</label><div class="metric">${uniq}</div></div><div class="card"><label>Voci XP</label><div class="metric">${entries.length}</div></div><div class="card"><label>XP assegnati</label><div class="metric">${fmt(xp)}</div></div></section><div class="grid"><section class="panel"><div class="panelhead"><h2>Sessioni recenti</h2><button class="link" data-page="sessions">Apri registro →</button></div>${groupTable(recent,false)}</section><section class="panel"><div class="panelhead"><h2>Classifica XP</h2><button class="link" data-page="players">Tutti →</button></div>${top.map((p,i)=>`<div class="rank"><span class="rankno">${i+1}</span><button class="link" data-open="${p.id}">${esc(p.name)}</button><b class="accent">${fmt(ts.get(p.id)||0)} XP</b></div>`).join('')}</section></div><div class="grid"><section class="panel"><div class="panelhead"><h2>XP assegnati negli ultimi mesi</h2></div>${monthChart()}</section></div>`}
function playerPage(){let statuses=[...new Set(['Attivo','Inattivo',...players.map(p=>p.status||'Attivo')])].sort((a,b)=>a.localeCompare(b));return `<section class="player-intro"><div><div class="eyebrow">Archivio della compagnia</div><h2>Le schede degli avventurieri</h2><p class="sub">Cerca, confronta i progressi e apri la storia di ogni personaggio.</p></div>${canEdit()?'<button class="action" id="newPlayer">＋ Aggiungi avventuriero</button>':''}</section><div class="player-toolbar"><label class="player-search"><span>⌕</span><input id="pSearch" placeholder="Cerca nome, classe, stirpe o origine…" autocomplete="off"></label><select id="pStatus"><option value="">Tutti gli stati</option>${statuses.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="pSort"><option value="name">Ordina per nome</option><option value="xp">Ordina per XP</option></select><span class="player-count">${players.length} PG</span></div><div id="pcards" class="gridcards">${playerCards(players)}</div>`}
function playerCards(list){let ts=totals();return list.map(p=>{let xp=ts.get(p.id)||0,rows=entries.filter(x=>x.player_id===p.id),lvl=levelInfo(xp);return `<article class="person person-polished${(p.status||'Attivo')==='Inattivo'?' is-inactive':''}"><div class="person-topline"><span class="tag">${esc(p.status||'Attivo')}</span><button class="link" data-open="${p.id}" aria-label="Apri la scheda di ${esc(p.name)}">Apri scheda ↗</button></div><div class="person-identity">${p.portrait_url?`<img class="portrait-small" src="${esc(p.portrait_url)}" alt="Ritratto di ${esc(p.name)}" loading="lazy">`:'<span class="portrait-placeholder">♙</span>'}<div><h3>${esc(p.name)}</h3><p>${esc(p.class||'Classe da aggiungere')} <span>·</span> ${esc(p.race||'Stirpe da aggiungere')}</p></div></div><div class="person-progress"><div><span>Livello ${lvl.level}${lvl.maxed?' · massimo':''}</span><b>${fmt(xp)} XP</b></div><div class="progress-track"><i data-w="${lvl.pct}"></i></div><small>${lvl.maxed?'Livello massimo raggiunto':`${fmt(lvl.remaining)} XP al livello ${lvl.level+1}`}</small></div><div class="person-meta"><span>▤ ${rows.length} sessioni</span><span>${lvl.maxed?'Livello 20':'Obiettivo '+fmt(lvl.next)+' XP'}</span></div><div class="personactions">${canEdit()?`<button class="quiet" data-edit="${p.id}">Modifica scheda</button><button class="link danger" data-archive="${p.id}">Archivia</button>`:''}</div></article>`}).join('')||'<div class="empty">Nessun avventuriero corrisponde ai filtri.</div>'}
function groups(){let m=new Map();entries.forEach(x=>{let k=[x.date,x.type,x.title].join('|'),g=m.get(k)||{key:k,date:x.date,type:x.type,title:x.title,rows:[],xp:0,author:''};g.rows.push(x);if(!g.author&&x.created_by)g.author=x.created_by;g.xp+=Number(x.xp||0);m.set(k,g)});return [...m.values()].map(g=>({...g,detail:adventures.find(a=>a.date===g.date&&a.type===g.type&&a.title===g.title)||null})).sort((a,b)=>b.date.localeCompare(a.date)||a.title.localeCompare(b.title))}
function groupTable(gs,actions=false){return `<div class="scroll"><table><thead><tr><th>Data</th><th>PG</th><th>Avventura</th><th>Tipo</th><th>XP totali</th><th>Inserita da</th></tr></thead><tbody>${gs.map(g=>`<tr class="clickrow" data-group="${encodeURIComponent(g.key)}"><td>${date(g.date)}</td><td>${g.rows.length}</td><td>${esc(g.title)}${g.detail?.summary?'<span class="tiny-note"> · Diario</span>':''}</td><td><span class="tag">${esc(g.type)}</span></td><td class="accent">${fmt(g.xp)}</td><td>${g.author?esc(g.author):'<span class="sub">—</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessuna avventura ancora.</td></tr>'}</tbody></table></div>`}
function adventurePage(){let g=selectedAdventure;if(!g)return sessionPage();let d=g.detail||{};return `<button class="link" data-page="sessions">← Torna al registro</button><section class="panel"><div class="eyebrow">${esc(g.type)} · ${date(g.date)}</div><h2>${esc(g.title)}</h2><p class="sub">${esc(d.location||'')} · ${g.rows.length} partecipanti · <b class="accent">${fmt(g.xp)} XP complessivi</b> · inserita da <b>${g.author?esc(g.author):'—'}</b></p><div class="panelhead section-title"><h3>Diario della sessione</h3>${canEdit()?'<button class="quiet" id="editAdventure">Modifica diario</button> <button class="link danger" data-delete-session="'+encodeURIComponent(g.key)+'">Elimina sessione</button>':''}</div>${d.summary?`<div class="detailtext">${esc(d.summary)}</div>`:'<p class="sub">Nessun riassunto aggiunto.</p>'}<h3 class="section-title">Partecipanti e XP</h3>${entryTable(g.rows)}</section>`}
function detailPage(){let p=players.find(x=>x.id===page.slice(7));if(!p){page='players';return playerPage()}let es=entries.filter(x=>x.player_id===p.id).sort((a,b)=>b.date.localeCompare(a.date)),xp=totals().get(p.id)||0,lvl=levelInfo(xp);return `<button class="link" data-page="players">← Avventurieri</button><section class="panel"><div class="person-heading">${p.portrait_url?`<img class="portrait" src="${esc(p.portrait_url)}" alt="Ritratto di ${esc(p.name)}">`:''}<div class="person-heading-main"><div class="eyebrow">Scheda avventuriero · ${esc(p.status||'Attivo')}</div><h2>${esc(p.name)}</h2><p class="sub">${esc(p.class||'Classe non indicata')} · ${esc(p.race||'Stirpe non indicata')}</p><p><span class="tag">Livello ${lvl.level}</span> ${p.alignment?`<span class="tag">${esc(p.alignment)}</span>`:''}</p></div>${p.google_sheet_url?`<a class="action" href="${esc(p.google_sheet_url)}" target="_blank" rel="noopener noreferrer">Apri Google Fogli ↗</a>`:''}</div><section class="cards mini-cards"><div class="card"><label>XP totali</label><div class="metric">${fmt(xp)}</div></div><div class="card"><label>Prossimo livello</label><div class="metric small-metric">${lvl.maxed?'Massimo':fmt(lvl.remaining)+' XP'}</div></div><div class="card"><label>Sessioni frequentate</label><div class="metric">${es.length}</div></div><div class="card"><label>Origine</label><div class="metric small-metric">${esc(p.background||'—')}</div></div><div class="card"><label>Compleanno</label><div class="metric small-metric">${dateBirthday(p.birthday)}</div></div></section>${p.details?`<h3 class="section-title">Altri dettagli</h3><div class="detailtext">${esc(p.details)}</div>`:''}${p.notes?`<h3 class="section-title">Note</h3><div class="detailtext">${esc(p.notes)}</div>`:''}${canEdit()?`<button class="quiet section-title" data-edit="${p.id}">Modifica scheda</button>`:''}<h3 class="section-title">Sessioni e XP</h3>${entryTable(es)}</section>`}
function entryTable(es,showPlayer=page==='adventure'){let playerColumn=showPlayer?'<th>PG</th>':'',authorColumn=showPlayer?'<th>Inserita da</th>':'';return `<div class="scroll"><table><thead><tr><th>Data</th>${playerColumn}<th>Avventura</th><th>Tipo</th><th>XP</th><th>Note</th>${authorColumn}${canEdit()?'<th>Azioni</th>':''}</tr></thead><tbody>${es.map(x=>`<tr><td>${date(x.date)}</td>${showPlayer?`<td>${esc(x.player_name)}</td>`:''}<td>${esc(x.title)}</td><td>${esc(x.type)}</td><td class="accent">${fmt(x.xp)}</td><td>${esc(x.notes)}</td>${showPlayer?`<td>${x.created_by?esc(x.created_by):'<span class="sub">—</span>'}</td>`:''}${canEdit()?`<td class="nowrap"><button class="link" data-edit-entry="${x.id}">Modifica</button> <button class="link danger" data-delete-entry="${x.id}">Elimina</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${(canEdit()?6:5)+(showPlayer?2:0)}" class="empty">Nessuna voce XP.</td></tr>`}</tbody></table></div>`}
function date(d){return d?new Date(d+'T12:00:00').toLocaleDateString('it-IT'):'—'}function dateBirthday(d){return d?date('2000'+d.slice(4)):'—'}
function schemaPanel(){if(!isAdmin())return '';const s=schemaStatus;if(!s)return `<section class="panel"><div class="panelhead"><h2>Stato del database</h2></div><p class="sub">Non è stato possibile verificare lo schema delle tabelle.</p></section>`;if(s.ok)return `<section class="panel"><div class="panelhead"><h2>Stato del database</h2><span class="tag">allineato</span></div><p class="sub">Tutte le tabelle e le colonne previste dal codice sono presenti (${s.tables} tabelle).</p></section>`;const items=[...(s.missing||[]),...(s.stale||[])];return `<section class="panel"><div class="panelhead"><h2>Stato del database</h2><span class="tag">da aggiornare</span></div><div class="notice">Manca o non è aggiornato: <b>${esc(items.join(', '))}</b>. Applica la migrazione mancante con:<br><code>npx wrangler d1 execute arcamis-register --remote --file migrations/0006_diary_trash_and_drop_attendance.sql</code></div></section>`}
function adminPage(){return `${schemaPanel()}<section class="panel"><div class="panelhead"><h2>Account della compagnia</h2><button class="action" id="newUser">Crea nuovo account</button></div><div class="notice">Solo l’amministratore crea e gestisce gli account. Tutti gli account attivi possono consultare l’intero archivio.</div><div class="scroll"><table><thead><tr><th>Nome utente</th><th>Ruolo</th><th>Creato</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.username)}${u.id===me.id?' <span class="tag">Tu</span>':''}${u.username.trim().toLowerCase()===PROTECTED_USERNAME?' <span class="tag">protetto</span>':''}</td><td><select class="role-select" data-role-user="${u.id}" ${(u.id===me.id||u.username.trim().toLowerCase()===PROTECTED_USERNAME)?'disabled':''}><option value="admin" ${u.role==='admin'?'selected':''}>Amministratore</option><option value="editor" ${u.role==='editor'?'selected':''}>Editor</option><option value="viewer" ${u.role==='viewer'?'selected':''}>Visualizzatore</option></select></td><td>${date(u.created_at.slice(0,10))}</td><td>${u.active?'Attivo':'Disattivato'}</td><td>${u.active?`<button class="link" data-reset="${u.id}">Reimposta password</button> ${(u.id!==me.id&&u.username.trim().toLowerCase()!==PROTECTED_USERNAME)?`<button class="link danger" data-disable="${u.id}">Disattiva</button>`:''}`:`<button class="link" data-activate="${u.id}">Riattiva</button>`}${u.id!==me.id?` <button class="link danger" data-delete-user="${u.id}">Elimina</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Archivio dati</h2><div class="tool-grid"><div><h3>Importazione iniziale JSON</h3><p class="sub">Per caricare il registro Excel convertito e preparato come archivio del progetto, solo su database vuoto.</p><input type="file" id="importFile" accept="application/json,.json"><button class="quiet section-title" id="doImport">Importa archivio</button><span id="importResult" class="sub"></span></div><div><h3>Aggiungi sessioni da CSV</h3><p class="sub">Intestazioni consigliate: data, pg, avventura, tipo, xp, note. Usa i nomi dei PG già presenti.</p><input type="file" id="csvFile" accept="text/csv,.csv"><div id="csvPreview" class="sub"></div><button class="quiet section-title" id="doCsvImport" disabled>Importa righe CSV</button></div><div><h3>Backup completo</h3><p class="sub">Scarica PG attivi e archiviati, sessioni, diari e utenti senza password.</p><button class="quiet" id="backup">Scarica backup JSON</button></div><div><h3>Foglio di calcolo</h3><p class="sub">Esporta il registro XP in CSV, compatibile con Excel e Google Fogli.</p><button class="quiet" id="adminCsvExport">Esporta registro CSV</button></div></div></section><section class="panel"><div class="panelhead"><h2>Personaggi archiviati</h2><span class="sub">La cronologia XP resta conservata.</span></div>${archivedPlayers.length?`<div class="scroll"><table><thead><tr><th>Nome</th><th>Classe</th><th>Stirpe</th><th></th></tr></thead><tbody>${archivedPlayers.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.class)}</td><td>${esc(p.race)}</td><td><button class="link" data-restore-player="${p.id}">Ripristina</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="sub">Nessun avventuriero archiviato.</p>'}</section><section class="panel"><div class="panelhead"><h2>Registro delle modifiche</h2><span class="sub">Ultime ${auditLog.length} attività registrate.</span></div>${auditLog.length?`<div class="scroll"><table><thead><tr><th>Quando</th><th>Account</th><th>Azione</th><th>Elemento</th><th>Dettaglio</th></tr></thead><tbody>${auditLog.map(x=>`<tr><td>${dateTime(x.created_at)}</td><td>${esc(x.username)}</td><td>${esc(x.action)}</td><td>${esc(x.entity)}</td><td>${esc(x.summary)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="sub">Le prossime modifiche appariranno qui.</p>'}</section>`}
function bindPage(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{setPage('detail-'+b.dataset.open)});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>playerForm(players.find(p=>p.id===b.dataset.edit)));document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=async()=>{if(confirm('Archiviare questo PG? La sua cronologia XP resterà negli annali.')){try{await api('players/'+b.dataset.archive,{method:'DELETE'});await load()}catch(e){alert(e.message)}}});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>showGroup(decodeURIComponent(b.dataset.group)));document.querySelectorAll('[data-edit-entry]').forEach(b=>b.onclick=()=>entryForm(entries.find(x=>x.id===b.dataset.editEntry)));document.querySelectorAll('[data-delete-entry]').forEach(b=>b.onclick=async()=>{if(confirm('Eliminare questa voce XP? L’azione verrà registrata.'))try{await api('entries/'+b.dataset.deleteEntry,{method:'DELETE'});await load()}catch(e){alert(e.message)}});document.querySelectorAll('[data-delete-session]').forEach(b=>b.onclick=async()=>{const parts=decodeURIComponent(b.dataset.deleteSession||'').split('|'),date=parts[0]||'',type=parts[1]||'',title=parts.slice(2).join('|');if(!title)return;if(!confirm('Eliminare la sessione «'+title+'» del '+date()+'?\n\nLe voci XP di tutti i partecipanti finiscono nel cestino (recuperabili). Il diario della sessione viene eliminato.'))return;try{await api('sessions?date='+encodeURIComponent(date)+'&type='+encodeURIComponent(type)+'&title='+encodeURIComponent(title),{method:'DELETE'});setPage('sessions');await load()}catch(e){alert(e.message)}});if($('#pSearch'))$('#pSearch').oninput=filterPlayers;$('#pStatus')?.addEventListener('change',filterPlayers);$('#pSort')?.addEventListener('change',filterPlayers);['sSearch','sType','sPlayer','sFrom','sTo','sSort'].forEach(id=>$('#'+id)?.addEventListener('input',filterSessions));$('#csvExport')?.addEventListener('click',()=>exportCSV(filteredGroups().flatMap(g=>g.rows)));$('#adminCsvExport')?.addEventListener('click',()=>exportCSV(entries));$('#newPlayer')?.addEventListener('click',()=>playerForm());$('#newUser')?.addEventListener('click',()=>userForm());$('#doImport')?.addEventListener('click',importData);$('#backup')?.addEventListener('click',backup);$('#csvFile')?.addEventListener('change',previewCSV);$('#doCsvImport')?.addEventListener('click',importCSV);document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>userForm(users.find(u=>u.id===b.dataset.reset)));document.querySelectorAll('[data-disable]').forEach(b=>b.onclick=()=>setUser(b.dataset.disable,{active:false}));document.querySelectorAll('[data-activate]').forEach(b=>b.onclick=()=>setUser(b.dataset.activate,{active:true}));document.querySelectorAll('[data-role-user]').forEach(b=>b.onchange=()=>setUser(b.dataset.roleUser,{role:b.value}));document.querySelectorAll('[data-delete-user]').forEach(b=>b.onclick=()=>deleteUser(b.dataset.deleteUser));document.querySelectorAll('[data-restore-player]').forEach(b=>b.onclick=async()=>{await put('players/'+b.dataset.restorePlayer,{active:true});await load()});$('#editAdventure')?.addEventListener('click',()=>adventureForm(selectedAdventure));document.querySelectorAll('[data-page]').forEach(()=>{});}
function filterPlayers(){let q=$('#pSearch').value.toLocaleLowerCase('it'),status=$('#pStatus').value,sort=$('#pSort').value,ts=totals(),list=players.filter(p=>(!status||(p.status||'Attivo')===status)&&[p.name,p.class,p.race,p.background,p.alignment,p.status].join(' ').toLocaleLowerCase('it').includes(q));list.sort((a,b)=>sort==='xp'?(ts.get(b.id)||0)-(ts.get(a.id)||0):sort==='__none__'?entries.filter(x=>x.player_id===b.id).length-entries.filter(x=>x.player_id===a.id).length:a.name.localeCompare(b.name,'it'));$('#pcards').innerHTML=playerCards(list);bindPage();applyDynamicStyles()}
function filteredGroups(){let q=$('#sSearch')?.value.toLocaleLowerCase('it')||'',t=$('#sType')?.value||'',player=$('#sPlayer')?.value||'',from=$('#sFrom')?.value||'',to=$('#sTo')?.value||'',sort=$('#sSort')?.value||'recent';let gs=groups().filter(g=>(!t||g.type===t)&&(!from||g.date>=from)&&(!to||g.date<=to)&&(!player||g.rows.some(x=>x.player_name===player))&&[g.title,g.type,g.detail?.summary,g.detail?.location,...g.rows.map(x=>x.player_name+' '+x.notes)].join(' ').toLocaleLowerCase('it').includes(q));gs.sort(sort==='oldest'?(a,b)=>a.date.localeCompare(b.date):sort==='xp'?(a,b)=>b.xp-a.xp:sort==='name'?(a,b)=>a.title.localeCompare(b.title,'it'):(a,b)=>b.date.localeCompare(a.date));return gs}
function filterSessions(){let gs=filteredGroups(),holder=$('#sessionRows');if(!holder)return;holder.innerHTML=groupTable(gs);$('#sessionCount').textContent=gs.length+' sessioni';holder.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>showGroup(decodeURIComponent(b.dataset.group)))}
function openModal(title,content,submit,label='Salva'){let m=$('#modal');m.innerHTML=`<form class="dialog" id="modalForm"><div class="panelhead"><h2>${title}</h2><button type="button" class="quiet" id="closeModal">Chiudi</button></div>${content}<div class="buttons"><button type="button" class="quiet" id="cancelModal">Annulla</button><button class="action">${label}</button></div><div class="error"></div></form>`;m.classList.add('open');$('#closeModal').onclick=$('#cancelModal').onclick=()=>m.classList.remove('open');$('#modalForm').onsubmit=async e=>{e.preventDefault();try{await submit(new FormData(e.target));m.classList.remove('open');await load()}catch(x){message(e.target,x.message)}}}
function playerForm(p=null){let edit=!!p;openModal(edit?'Modifica scheda PG':'Aggiungi avventuriero',`<div class="formgrid"><label>Nome PG<input name="name" required value="${esc(p?.name)}"></label><label>Classe<input name="class" value="${esc(p?.class)}"></label><label>Stirpe / razza<input name="race" value="${esc(p?.race)}"></label><label>Origine<input name="background" value="${esc(p?.background)}"></label><label>Allineamento<input name="alignment" value="${esc(p?.alignment)}"></label><label>Stato<select name="status">${[...new Set(['Attivo','Inattivo',p?.status||'Attivo',...players.map(x=>x.status||'Attivo')])].map(x=>`<option ${x===(p?.status||'Attivo')?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Compleanno<input name="birthday" type="date" value="${esc(p?.birthday)}"></label><label class="wide">Link immagine del PG<input name="portrait_url" type="url" placeholder="https://…" value="${esc(p?.portrait_url)}"></label><label class="wide">Note brevi<input name="notes" value="${esc(p?.notes)}"></label><label class="wide">Altri dettagli<textarea name="details">${esc(p?.details)}</textarea></label>${isAdmin()?`<label class="wide">Link Google Fogli del PG<input name="google_sheet_url" type="url" placeholder="https://docs.google.com/spreadsheets/d/…" value="${esc(p?.google_sheet_url)}"><small>Solo l’amministratore può aggiungere o cambiare questo collegamento.</small></label>`:'<div class="notice wide">Il collegamento Google Fogli può essere modificato solo dall’amministratore.</div>'}</div>`,async f=>{let d=Object.fromEntries(f);if(edit)await put('players/'+p.id,d);else await post('players',d)})}
function typesSelect(current='Principale'){let types=[...new Set(['Principale','Secondaria','Evento','Improvvisata','Staff',current].filter(Boolean))];return types.map(t=>`<option ${t===current?'selected':''}>${esc(t)}</option>`).join('')}
function entryForm(entry=null){let editing=!!entry;openModal(editing?'Modifica voce XP':'Registra XP',`<div class="formgrid"><label>Data<input name="date" type="date" value="${esc(entry?.date||todayISO())}" required></label><label>Avventuriero<select name="player_id">${players.map(p=>`<option value="${p.id}" ${p.id===entry?.player_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Tipo<select name="type">${typesSelect(entry?.type)}</select></label><label>XP (negativo per togliere)<input name="xp" type="number" step="1" value="${esc(entry?.xp??'')}" required></label><label class="wide">Nome avventura<input name="title" value="${esc(entry?.title)}" required></label><label class="wide">Note<input name="notes" value="${esc(entry?.notes)}"></label></div>`,async f=>editing?put('entries/'+entry.id,Object.fromEntries(f)):post('entries',Object.fromEntries(f)))}
function adventureForm(g){let d=g.detail||{};openModal('Diario della sessione',`<div class="formgrid"><label>Data<input type="date" value="${esc(g.date)}" disabled></label><label>Tipo<input value="${esc(g.type)}" disabled></label><label class="wide">Sessione<input value="${esc(g.title)}" disabled></label><label class="wide">Luogo<input name="location" maxlength="200" value="${esc(d.location)}"></label><label class="wide">Riassunto<textarea name="summary" maxlength="12000" placeholder="Cosa è successo durante questa sessione?">${esc(d.summary)}</textarea></label></div>`,async f=>{let values=Object.fromEntries(f);await put('adventures',{...values,date:g.date,type:g.type,title:g.title})})}
function userForm(u=null){let editing=!!u;openModal(editing?`Gestisci account · ${esc(u.username)}`:'Crea un nuovo account',`<div class="notice">${editing?'Cambia ruolo o imposta una nuova password. Le sessioni vengono chiuse quando la password cambia.':'Scegli nome utente, ruolo e una password iniziale di almeno 12 caratteri. Dopo la creazione, comunica la password al membro in modo privato.'}</div><div class="formgrid">${editing?`<label>Ruolo<select name="role"><option value="admin" ${u.role==='admin'?'selected':''}>Amministratore</option><option value="editor" ${u.role==='editor'?'selected':''}>Editor</option><option value="viewer" ${u.role==='viewer'?'selected':''}>Visualizzatore</option></select></label><label>Stato<select name="active"><option value="1" ${u.active?'selected':''}>Attivo</option><option value="0" ${!u.active?'selected':''}>Disattivato</option></select></label><label class="wide">Nuova password (facoltativa)<input name="password" type="password" minlength="12" autocomplete="new-password"></label>`:`<label>Nome utente<input name="username" minlength="3" maxlength="50" autocomplete="off" required></label><label>Ruolo<select name="role"><option value="viewer">Visualizzatore</option><option value="editor">Editor</option><option value="admin">Amministratore</option></select></label><label class="wide">Password iniziale<input name="password" type="password" minlength="12" autocomplete="new-password" required></label>`}</div>`,async f=>{let d=Object.fromEntries(f);if(d.active!==undefined)d.active=d.active==='1';if(editing)await put('users/'+u.id,d);else await post('users',d)},editing?'Salva modifiche':'Crea account')}
async function setUser(uid,body){try{await put('users/'+uid,body);await load()}catch(e){alert(e.message);await load()}}
function deleteUser(id){const u=users.find(x=>x.id===id);if(!u)return;const prot=u.username.trim().toLowerCase()===PROTECTED_USERNAME;if(!prot){if(!confirm('Eliminare definitivamente le credenziali di «'+u.username+'»? L’account non potrà più accedere e le sue sessioni vengono chiuse.'))return;api('users/'+id,{method:'DELETE'}).then(()=>load()).catch(e=>alert(e.message));return}openModal('Elimina l’account protetto',`<div class="notice">«${esc(u.username)}» è l’account protetto: senza la password di servizio non può essere eliminato, declassato o disattivato. La password è il secret <b>ADMIN_DELETE_SECRET</b> impostato su Cloudflare (Impostazioni → Variabili e segreti del progetto). L’eliminazione è definitiva.</div><label>Password di protezione<input name="secret" type="password" autocomplete="off" required></label>`,async f=>{await api('users/'+id,{method:'DELETE',body:JSON.stringify({secret:Object.fromEntries(f).secret})})},'Elimina account')}
function showGroup(key){selectedAdventure=groups().find(x=>x.key===key);if(!selectedAdventure)return;setPage('adventure')}
function exportCSV(rows){let cols=['data','avventura','tipo','pg','xp','note'],q=x=>{let v=String(x??'');if(/^[\s]*[=+@]/.test(v)||/^[\s]*-[^\d]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'},csv=[cols.join(';'),...rows.map(x=>[x.date,x.title,x.type,x.player_name,x.xp,x.notes].map(q).join(';'))].join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});download(blob,'arcamis-registro-xp.csv')}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function backup(){try{let data=await api('backup');download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'arcamis-backup-'+todayISO()+'.json')}catch(e){alert(e.message)}}
async function importData(){let file=$('#importFile').files[0],result=$('#importResult');if(!file){result.textContent=' Scegli prima il file JSON.';return}try{let data=JSON.parse((await file.text()).replace(/^\uFEFF/,'')),r=await post('import',data);result.textContent=` Importati ${r.players} PG e ${r.entries} voci XP.`;await load()}catch(e){result.textContent=' '+e.message}}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false,head=text.split(/\r?\n/,1)[0],delimiter=(head.match(/;/g)||[]).length>(head.match(/,/g)||[]).length?';':',';for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===delimiter){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}let headers=(rows.shift()||[]).map(h=>h.trim().toLocaleLowerCase('it').normalize('NFD').replace(/[\u0300-\u036f]/g,'')),ix=(...names)=>headers.findIndex(h=>names.includes(h));let iDate=ix('data','date'),iPlayer=ix('pg','personaggio','avventuriero','player'),iTitle=ix('avventura','titolo','sessione','title'),iType=ix('tipo','type'),iXp=ix('xp','esperienza'),iNotes=ix('note','notes');if([iDate,iPlayer,iTitle,iXp].some(i=>i<0))throw Error('Intestazioni mancanti: servono almeno data, pg, avventura e xp.');return rows.filter(r=>r.some(x=>x.trim())).map(r=>({date:csvDate(r[iDate]||''),player:r[iPlayer]||'',title:r[iTitle]||'',type:r[iType]||'Principale',xp:Number(String(r[iXp]||'').replace(',','.'))||0,notes:iNotes>=0?r[iNotes]||'':''}))}
function csvDate(s){s=String(s).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s;let m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);return m?`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`:s}
async function importCSV(){if(!csvRows.length)return;let unknown=csvRows.map(x=>x.player).filter(name=>!players.some(p=>p.name.toLocaleLowerCase('it')===name.trim().toLocaleLowerCase('it')));if(unknown.length){alert('Aggiungi prima i personaggi mancanti: '+[...new Set(unknown)].join(', '));return}if(!confirm(`Aggiungere fino a ${csvRows.length} voci XP? Le righe duplicate verranno saltate.`))return;try{let r=await post('import-csv',{entries:csvRows});alert(`Importate ${r.added} voci; ${r.skipped} duplicate o non valide ignorate.`);csvRows=[];await load()}catch(e){alert(e.message)}}
async function load(){try{[players,entries,adventures,prefs]=await Promise.all([api('players'),api('entries'),api('adventures'),api('settings')]);if(canEdit()){trashError='';[trash,trashAdventures]=await Promise.all([api('trash').catch(e=>{trashError=trashError||e.message;return[]}),api('adventure-trash').catch(e=>{trashError=trashError||e.message;return[]})])}else{trash=[];trashAdventures=[];trashError=''}if(isAdmin())[users,archivedPlayers,auditLog,quality,schemaStatus]=await Promise.all([api('users'),api('archived-players'),api('audit'),api('quality'),api('schema-status').catch(()=>null)]);else{users=[];archivedPlayers=[];auditLog=[];schemaStatus=null;quality={players:[],entries:[]}}if(page==='adventure'&&selectedAdventure)selectedAdventure=groups().find(x=>x.key===selectedAdventure.key)||selectedAdventure;clearLoadError();render()}catch(e){if(e.status===401)return login(e.message);showLoadError(e.message)}}
function dateTime(d){return d?new Date(d).toLocaleString('it-IT',{dateStyle:'short',timeStyle:'short'}):'Da aggiornamento'}
function alerts(){let window=Number(prefs.xp_reminder_window)||0,ts=totals(),near=[...players].map(p=>({p,v:levelInfo(ts.get(p.id)||0)})).filter(x=>!x.v.maxed&&x.v.remaining<=window).sort((a,b)=>a.v.remaining-b.v.remaining).slice(0,5),birthdays=prefs.birthday_reminders?players.map(p=>({p,days:daysToBirthday(p.birthday)})).filter(x=>x.days!==null&&x.days<=7).sort((a,b)=>a.days-b.days):[];return `<section class="panel"><div class="panelhead"><h2>Promemoria della compagnia</h2><span class="tag">${near.length+birthdays.length}</span></div>${birthdays.map(x=>`<p>🎂 ${esc(x.p.name)} · ${x.days===0?'oggi':`tra ${x.days} giorni`}</p>`).join('')}${near.map(x=>`<p>✧ ${esc(x.p.name)} è a ${fmt(x.v.remaining)} XP dal livello ${x.v.level+1}.</p>`).join('')}${!near.length&&!birthdays.length?'<p class="sub">Nessun compleanno o traguardo imminente.</p>':''}</section>`}
function sessionPage(){let types=[...new Set(entries.map(x=>x.type))],playersUsed=[...new Set(entries.map(x=>x.player_name))].sort((a,b)=>a.localeCompare(b));return `<div class="searchrow filters"><input id="sSearch" placeholder="Cerca avventura, luogo, diario o PG…"><select id="sType"><option value="">Tutti i tipi</option>${types.map(t=>`<option>${esc(t)}</option>`).join('')}</select><select id="sPlayer"><option value="">Tutti i PG</option>${playersUsed.map(p=>`<option>${esc(p)}</option>`).join('')}</select><label class="compact-label">Dal<input id="sFrom" type="date"></label><label class="compact-label">Al<input id="sTo" type="date"></label><select id="sSort"><option value="recent">Più recenti</option><option value="oldest">Meno recenti</option><option value="xp">Più XP</option><option value="name">Nome avventura</option></select><button class="quiet" id="csvExport">Scarica CSV</button>${canEdit()?`<select id="sessionPreset"><option value="">Filtri salvati…</option>${filterPresets().map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('')}</select><button class="quiet" id="sessionPresetSave">Salva filtri</button><button class="quiet" id="openTrash">Cestino · ${trash.length}</button>`:''}</div><section class="panel"><div class="panelhead"><h2 id="sessionCount">${groups().length} sessioni</h2><span class="sub">Apri una riga per vedere i partecipanti e il diario.</span></div><div id="sessionRows">${groupTable(groups())}</div></section>`}
function filterPresets(){try{return JSON.parse(localStorage.getItem('arcamis-session-filters')||'[]')}catch{return []}}
function saveFilterPreset(){let name=prompt('Nome per questo filtro salvato:');if(!name?.trim())return;let list=filterPresets();list.push({name:name.trim(),q:$('#sSearch').value,type:$('#sType').value,player:$('#sPlayer').value,from:$('#sFrom').value,to:$('#sTo').value,sort:$('#sSort').value});localStorage.setItem('arcamis-session-filters',JSON.stringify(list.slice(-12)));render()}
function applyFilterPreset(){let p=filterPresets()[Number($('#sessionPreset').value)];if(!p)return;for(const [id,key] of [['sSearch','q'],['sType','type'],['sPlayer','player'],['sFrom','from'],['sTo','to'],['sSort','sort']])$('#'+id).value=p[key]||'';filterSessions()}
function sessionForm(){let options=players.map(p=>`<label class="participant-option"><span><input name="participant" type="checkbox" value="${p.id}"> ${esc(p.name)}</span><input aria-label="XP per ${esc(p.name)}" name="xp_${p.id}" type="number" step="1" value="0"></label>`).join('');openModal('Registra una sessione',`<div class="formgrid"><label>Data<input name="date" type="date" value="${todayISO()}" required></label><label>Tipo<select name="type">${typesSelect('Principale')}</select></label><label class="wide">Nome avventura<input name="title" required></label><label class="wide">Luogo<input name="location" maxlength="200"></label><label class="wide">Riassunto / diario<textarea name="summary" maxlength="12000" placeholder="Aggiungi gli eventi principali della sessione…"></textarea></label></div><h3 class="section-title">Partecipanti e XP individuali</h3><input id="sessionPlayerSearch" placeholder="Filtra i personaggi…"><div class="participant-list">${options}</div>`,async f=>{let ids=f.getAll('participant');if(!ids.length)throw Error('Seleziona almeno un partecipante.');let d=Object.fromEntries(f);d.participants=ids.map(id=>({player_id:id,xp:d['xp_'+id]||0}));await post('sessions',d)}) ;$('#sessionPlayerSearch').oninput=e=>document.querySelectorAll('.participant-option').forEach(n=>n.hidden=!n.textContent.toLocaleLowerCase('it').includes(e.target.value.toLocaleLowerCase('it')))}
function changePasswordForm(){openModal('Cambia la tua password',`<div class="notice">Usa almeno 12 caratteri. Le altre sessioni attive verranno chiuse.</div><div class="formgrid"><label class="wide">Password attuale<input name="current_password" type="password" autocomplete="current-password" required></label><label>Nuova password<input name="new_password" type="password" minlength="12" autocomplete="new-password" required></label><label>Conferma nuova password<input name="confirm_password" type="password" minlength="12" autocomplete="new-password" required></label></div>`,async f=>{let d=Object.fromEntries(f);if(d.new_password!==d.confirm_password)throw Error('Le due nuove password non coincidono.');await put('me',d)})}
function openTrash(){let m=$('#modal');m.innerHTML=`<div class="dialog"><div class="panelhead"><h2>Cestino</h2><button class="quiet" id="closeTrash">Chiudi</button></div><p class="sub">Voci XP e diari possono essere recuperati dagli editor e dall’amministratore. L’eliminazione definitiva è riservata all’amministratore.</p>${trashError?`<div class="notice">Cestino non disponibile in questo momento: ${esc(trashError)}</div>`:''}<div class="scroll"><table><thead><tr><th>Eliminata</th><th>PG</th><th>Avventura</th><th>XP</th><th></th></tr></thead><tbody>${trash.map(x=>`<tr><td>${dateTime(x.deleted_at)}</td><td>${esc(x.player_name)}</td><td>${esc(x.title)}</td><td>${fmt(x.xp)}</td><td><button class="link" data-restore-trash="${x.id}">Recupera</button>${isAdmin()?` <button class="link danger" data-purge-trash="${x.id}">Elimina</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Il cestino è vuoto.</td></tr>'}</tbody></table></div><h3 class="section-title">Diari di sessione eliminati</h3><p class="sub">Recuperando un diario tornano riassunto e luogo della sessione. Le voci XP si recuperano dalla tabella qui sopra.</p><div class="scroll"><table><thead><tr><th>Eliminato</th><th>Sessione</th><th>Data sessione</th><th></th></tr></thead><tbody>${trashAdventures.map(x=>`<tr><td>${dateTime(x.deleted_at)}</td><td>${esc(x.title)}</td><td>${date(x.date)}</td><td><button class="link" data-restore-diary="${x.id}">Recupera</button>${isAdmin()?` <button class="link danger" data-purge-diary="${x.id}">Elimina</button>`:''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun diario nel cestino.</td></tr>'}</tbody></table></div></div>`;m.classList.add('open');$('#closeTrash').onclick=()=>m.classList.remove('open');document.querySelectorAll('[data-restore-diary]').forEach(b=>b.onclick=async()=>{try{await post('adventure-trash/'+b.dataset.restoreDiary+'/restore',{});await load();openTrash()}catch(e){alert(e.message)}});document.querySelectorAll('[data-purge-diary]').forEach(b=>b.onclick=async()=>{if(confirm('Eliminare definitivamente questo diario?')){try{await api('adventure-trash/'+b.dataset.purgeDiary,{method:'DELETE'});await load();openTrash()}catch(e){alert(e.message)}}});document.querySelectorAll('[data-restore-trash]').forEach(b=>b.onclick=async()=>{await post('trash/'+b.dataset.restoreTrash+'/restore',{});await load();openTrash()});document.querySelectorAll('[data-purge-trash]').forEach(b=>b.onclick=async()=>{if(confirm('Eliminare definitivamente questa voce?')){await api('trash/'+b.dataset.purgeTrash,{method:'DELETE'});await load();openTrash()}})}
function adminExtrasHTML(){let live=users.filter(u=>u.active);return `<section class="panel"><div class="panelhead"><h2>Accessi recenti</h2><span class="sub">Ultimo accesso registrato per account.</span></div><div class="scroll"><table><thead><tr><th>Account</th><th>Ruolo</th><th>Ultimo accesso</th></tr></thead><tbody>${live.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(roleNames[u.role]||u.role)}</td><td>${dateTime(u.last_login)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Promemoria configurabili</h2><form id="settingsForm" class="formgrid"><label>Avviso entro quanti XP dal livello successivo<input name="xp_reminder_window" type="number" min="0" step="50" value="${prefs.xp_reminder_window}"></label><label class="wide">I livelli seguono la scala D&amp;D 5e: 20 livelli, da 0 XP (livello 1) a 355.000 XP (livello 20).</label><label class="wide checkline"><input type="checkbox" name="birthday_reminders" ${prefs.birthday_reminders?'checked':''}> Mostra i compleanni imminenti nella panoramica</label><div class="wide"><button class="action">Salva promemoria</button></div><div id="settingsMessage" class="sub wide"></div></form></section><section class="panel"><div class="panelhead"><h2>Controllo qualità archivio</h2><span class="sub">Campi che puoi completare dalle schede.</span></div>${quality.players.length||quality.entries.length?`<div class="scroll"><table><thead><tr><th>Elemento</th><th>Campi da controllare</th></tr></thead><tbody>${quality.players.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.missing.join(', '))}</td></tr>`).join('')}${quality.entries.map(x=>`<tr><td>${esc(x.title||'Voce XP senza avventura')} · ${esc(x.player_name)}</td><td>${!x.player_id?'associa PG':''}${!x.date?'data mancante':''}${!x.title?'titolo mancante':''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="sub">Tutti i controlli sono a posto.</p>'}</section><section class="panel"><h2>Ripristina da backup</h2><p class="sub">Il ripristino unisce i dati presenti nel backup a quelli attuali. Non elimina i dati che non sono nel file e non ripristina password o account.</p><input type="file" id="restoreBackupFile" accept="application/json,.json"><div id="restoreSummary" class="notice">Scegli un backup JSON completo per vedere l’anteprima.</div><button class="quiet" id="restoreBackupButton" disabled>Ripristina i dati del file</button></section><section class="panel"><div class="panelhead"><h2>Cestino XP</h2><button class="quiet" id="openTrash">Apri cestino · ${trash.length}</button></div><p class="sub">Le voci eliminate restano recuperabili finché non vengono rimosse definitivamente.</p></section>`}
function bindAdminExtras(){$('#settingsForm')?.addEventListener('submit',saveSettings);$('#restoreBackupFile')?.addEventListener('change',previewRestore);$('#restoreBackupButton')?.addEventListener('click',restoreBackup)}
async function saveSettings(e){e.preventDefault();try{const f=new FormData(e.target),d=Object.fromEntries(f);d.birthday_reminders=f.has('birthday_reminders');d.xp_milestone_step=Number(prefs.xp_milestone_step)||5000;await put('settings',d);await load()}catch(x){$('#settingsMessage').textContent=x.message}}
async function previewRestore(){let file=$('#restoreBackupFile').files[0],button=$('#restoreBackupButton'),box=$('#restoreSummary');restorePayload=null;button.disabled=true;if(!file){box.textContent='Scegli un backup JSON completo per vedere l’anteprima.';return}try{const d=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(d.format!=='arcamis-backup-v2'||!Array.isArray(d.players)||!Array.isArray(d.entries)||!Array.isArray(d.adventures))throw Error('Questo file non è un backup completo riconosciuto.');restorePayload=d;box.textContent=`Anteprima: ${d.players.length} PG, ${d.entries.length} voci XP, ${d.adventures.length} diari. Il ripristino aggiunge o aggiorna i record con lo stesso ID e conserva i dati estranei al file.`;button.disabled=false}catch(x){box.textContent=x.message}}
async function restoreBackup(){if(!restorePayload)return;if(!confirm(`Unire ${restorePayload.players.length} PG e ${restorePayload.entries.length} voci XP dal backup?`))return;try{const r=await post('restore',restorePayload);alert(`Ripristino completato: ${r.players} PG e ${r.entries} voci XP elaborate.`);restorePayload=null;await load()}catch(e){alert(e.message)}}
async function previewCSV(){let file=$('#csvFile')?.files[0],button=$('#doCsvImport'),box=$('#csvPreview');if(!file||!button||!box)return;button.disabled=true;csvRows=[];try{csvRows=parseCSV((await file.text()).replace(/^\uFEFF/,''));let lookup=new Map(players.map(p=>[p.name.trim().toLocaleLowerCase('it'),p.id])),unknown=[...new Set(csvRows.map(x=>x.player).filter(x=>!lookup.has(x.trim().toLocaleLowerCase('it'))))],invalid=csvRows.filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||!x.title.trim()).length,known=entries.map(x=>[x.player_id,x.date,x.type,x.title,x.xp,x.notes].join('|')),duplicates=csvRows.filter(x=>{let id=lookup.get(x.player.trim().toLocaleLowerCase('it'));return known.includes([id,x.date,x.type,x.title,x.xp,x.notes].join('|'))}).length;box.innerHTML=`<p>${csvRows.length} righe · ${invalid} non valide · ${duplicates} doppioni già presenti.${unknown.length?` Personaggi mancanti: ${esc(unknown.slice(0,8).join(', '))}.`:' Controlla l’anteprima prima di importare.'}</p><div class="scroll"><table><thead><tr><th>Data</th><th>PG</th><th>Avventura</th><th>XP</th></tr></thead><tbody>${csvRows.slice(0,5).map(x=>`<tr><td>${date(x.date)}</td><td>${esc(x.player)}</td><td>${esc(x.title)}</td><td>${fmt(x.xp)}</td></tr>`).join('')}</tbody></table></div>`;button.disabled=!csvRows.length||unknown.length>0}catch(e){box.textContent=e.message}}
function mobileNavStyle(){document.body.classList.toggle('compact-session',page==='sessions')}
function render(){let titles={home:'Panoramica',players:'Avventurieri',sessions:'Registro XP',admin:'Amministrazione',adventure:selectedAdventure?.title||'Avventura'};if(page.startsWith('detail-'))titles[page]='Scheda PG';app.innerHTML=`<div class="layout">${nav()}<main class="main"><header class="top"><div><div class="eyebrow">Benvenuto, ${esc(me.username)} · ${esc(roleNames[me.role]||'')}</div><h1>${esc(titles[page]||'Scheda PG')}</h1><p class="sub">Esperienza, presenze e reputazione della compagnia.</p></div><div class="top-actions">${canEdit()?'<button class="action" id="newSession">＋ Nuova sessione</button><button class="quiet" id="addEntry">Singolo XP</button> ':''}<button class="quiet" id="changePassword">Cambia password</button><button class="quiet" id="logout">Esci</button></div></header>${page==='home'?home():page==='players'?playerPage():page==='sessions'?sessionPage():page==='adventure'?adventurePage():page==='admin'&&isAdmin()?adminPage():page.startsWith('detail-')?detailPage():home()}${page==='admin'&&isAdmin()?`<div id="adminExtras">${adminExtrasHTML()}</div>`:''}</main></div><div class="modal" id="modal"></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{setPage(b.dataset.page)});$('#logout').onclick=async()=>{await post('logout',{});me=null;login()};$('#addEntry')?.addEventListener('click',()=>entryForm());$('#newSession')?.addEventListener('click',sessionForm);$('#changePassword')?.addEventListener('click',changePasswordForm);$('#openTrash')?.addEventListener('click',openTrash);bindPage();$('#sessionPresetSave')?.addEventListener('click',saveFilterPreset);$('#sessionPreset')?.addEventListener('change',applyFilterPreset);bindAdminExtras();mobileNavStyle();applyDynamicStyles()}
boot();

